export const transitionPartyRecord = Effect.fn(
  'PartyIdentityPersistenceService.transitionPartyRecord',
)(function* transitionParty(
  transaction: Pick<PartyTransaction, 'select' | 'update'>,
  tenantId: string,
  partyId: string,
  expectedRevision: number,
  state: 'ARCHIVED',
) {
  const current = yield* lockPartyIdentityRecord(transaction, tenantId, partyId);
  if (current === undefined) {
    return { _tag: 'not_found' } as const;
  }
  yield* requireCanonicalPartyWriteTarget(transaction, tenantId, partyId);
  const archived = current.archivedAt !== null;
  if (current.revision !== expectedRevision || archived === (state === 'ARCHIVED')) {
    return { _tag: 'conflict', value: partyDto(current) } as const;
  }
  const now = yield* DateTime.nowAsDate;
  const [updated] = yield* transaction
    .update(parties)
    .set({
      archivedAt: now,
      revision: current.revision + 1,
      updatedAt: now,
    })
    .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, partyId)))
    .returning()
    .pipe(Effect.mapError(unavailable));
  return updated === undefined
    ? yield* unavailable()
    : ({ _tag: 'found', value: partyDto(updated) } as const);
});

